insert into public.services (id, user_id, title, category, description, price, delivery_days, is_active, created_at, image_url) overriding system value values (2001, '00000000-0000-4000-8000-000000001002', 'I will design a modern logo and brand kit for your business', 'Graphic Design', 'You get 3 logo concepts, unlimited revisions on your chosen concept, and a brand kit with colours, fonts and social media sizes.
insert into public.services (id, user_id, title, category, description, price, delivery_days, is_active, created_at, image_url) overriding system value values (2002, '00000000-0000-4000-8000-000000001002', 'I will create 10 branded social media post designs', 'Graphic Design', 'Eye-catching Instagram and Facebook posts in your brand colours, delivered as PNG and editable Canva links.', 2500, 2, true, '2026-10-03 10:35:27', NULL);
insert into public.services (id, user_id, title, category, description, price, delivery_days, is_active, created_at, image_url) overriding system value values (2003, '00000000-0000-4000-8000-000000001004', 'I will build a fast, mobile-friendly business website', 'Web Development', 'A 5-page responsive website (Home, About, Services, Gallery, Contact) built with Bootstrap, with WhatsApp chat button and Google Maps. Hosting setup included.', 18000, 10, true, '2026-10-06 10:35:27', NULL);
insert into public.services (id, user_id, title, category, description, price, delivery_days, is_active, created_at, image_url) overriding system value values (2004, '00000000-0000-4000-8000-000000001004', 'I will add M-Pesa payments to your website', 'Web Development', 'Integration of Lipa na M-Pesa (STK push) with your PHP or WordPress site, including testing on the sandbox and going live.', 12000, 5, true, '2026-10-09 10:35:27', NULL);
insert into public.services (id, user_id, title, category, description, price, delivery_days, is_active, created_at, image_url) overriding system value values (2005, '00000000-0000-4000-8000-000000001006', 'I will manage your Facebook and Instagram pages for a month', 'Social Media Management', 'Daily posts, captions in English and Kiswahili, replying to comments and a monthly report. Ideal for restaurants, salons and shops.', 9000, 30, true, '2026-10-12 10:35:27', NULL);
insert into public.services (id, user_id, title, category, description, price, delivery_days, is_active, created_at, image_url) overriding system value values (2006, '00000000-0000-4000-8000-000000001006', 'I will write engaging blog articles for your business', 'Writing & Translation', 'SEO-friendly 800-word articles researched for your audience. Kiswahili translation available.', 1500, 2, true, '2026-10-15 10:35:27', NULL);
insert into public.services (id, user_id, title, category, description, price, delivery_days, is_active, created_at, image_url) overriding system value values (2007, '00000000-0000-4000-8000-000000001002', 'I will design a professional company profile PDF', 'Graphic Design', 'A polished 6–10 page company profile ready to send to clients and tenders.', 6000, 5, true, '2026-10-18 10:35:27', NULL);
